// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // General rule to test (fuzzed): when starting from betLimit == 0 (constructor set),
    // calling AdjustBetAmounts(amount) will set betLimit == amount for the reference.
    // The mutant that does betLimit = betLimit + amount will instead produce betLimit != amount
    // for some fuzzed amounts. We fuzz `uint256 amount` to let the fuzzer find inputs that
    // distinguish the two behaviors.
    function testFuzz_property(uint256 amount) public {
        // keep domain wide but avoid trivial no-op: allow amount any value (including 0);
        // the property we assert holds for all admissible inputs on the reference
        // and is violated by the mutant for some inputs (e.g., any non-zero amount).

        // Call AdjustBetAmounts as the owner (setUp deployed c with address(this) as owner)
        bool ok;
        try c.AdjustBetAmounts(amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // After call, the reference contract (with initial betLimit == 0) must have betLimit == amount.
        // We observe via public getter currentBetLimit(). This is a single assertion reading c's public surface.
        // This assertion is true for the reference for all amounts, and false for the mutant when amount != 0
        // because the mutant would set betLimit = 0 + amount as well for a single call from 0, but
        // the mutant's intended difference is cumulative — to ensure distinction we perform two calls when needed.
        // However, to keep a single assertion and let the fuzzer find a distinguishing input, we exploit that
        // the mutant differs for sequences: call twice with same amount and expect betLimit == amount for reference
        // (idempotent set) but mutant will have doubled. We therefore perform a second call when first succeeded.

        if (ok) {
            // perform second call to reveal cumulative-add mutant behavior
            // second call also by owner
            bool ok2;
            try c.AdjustBetAmounts(amount) {
                ok2 = true;
            } catch {
                ok2 = false;
            }
            // Now reference: starting from 0, first call sets betLimit=amount, second call sets betLimit=amount again (idempotent set).
            // Mutant: first call sets betLimit=amount, second call sets betLimit=amount+amount=2*amount.
            // So assert that currentBetLimit() == amount (this holds for reference for all amount),
            // and will fail for the mutant when amount != 0.
            uint256 reported = c.currentBetLimit();
            assertTrue(reported == amount);
        } else {
            // If AdjustBetAmounts reverted, then the reference would revert too; keep assertion trivial but still read c
            // We must still make exactly one assertTrue reading c. If call reverted, betLimit remains initial 0.
            uint256 reported = c.currentBetLimit();
            assertTrue(reported == 0);
        }
    }
}

