    // the betLimit should equal the passed amount. The mutant that does betLimit = betLimit + amount
    // will make betLimit != amount for some inputs (any nonzero amount).
    function testFuzz_property(uint256 amount) public {
        // keep the domain wide but avoid potential overflow concerns when owner-only logic or events
        // are irrelevant here; amount can be any uint256. We call as the owner (deployer used in setUp()).
        // Ensure caller is owner (setUp deployed c with address(this) as owner)
        bool ok;
        try c.AdjustBetAmounts(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference contract never reverts on AdjustBetAmounts (owner call), so ok should be true for all inputs.
        // And after the call, the general property (reference) is: c.currentBetLimit() == amount when initial was 0.
        // We assert that: this holds for the reference for all amounts, and the mutant (which increments) will break
        // this assertion for some amounts (any nonzero), causing the test to fail on the mutant.
        assertTrue(ok && c.currentBetLimit() == amount);
    }
