pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // General rule: the deployer (msg.sender that constructed c) is owner; for any uint256 newLimit,
    // when that owner calls AdjustBetAmounts(newLimit) the contract's currentBetLimit() equals newLimit.
    // The mutant that changes owner check to whale will break this for calls made by the deployer when
    // whale != owner. We fuzz newLimit and the caller address flag (isCallerOwner) to let fuzzer explore.
    function testFuzz_property(uint256 newLimit, bool callerIsOwner) public {
        // Keep domain wide; no restrictive assume. We will choose caller address accordingly.
        address caller;
        if (callerIsOwner) {
            // the deployer (address(this)) is the owner per constructor; use that
            caller = address(this);
        } else {
            // pick some other EOA for non-owner caller
            caller = address(0xBEEF);
        }

        // Fund caller so calls (if needed) have gas; AdjustBetAmounts is non-payable so no value transfer.
        vm.deal(caller, 1 ether);

        bool ok;
        // perform the call as the chosen caller
        if (caller == address(this)) {
            // calling from this test contract (owner)
            try c.AdjustBetAmounts(newLimit) {
                ok = true;
            } catch {
                ok = false;
            }
        } else {
            vm.prank(caller);
            try c.AdjustBetAmounts(newLimit) {
                ok = true;
            } catch {
                ok = false;
            }
        }

        // Exactly one assertion: In the reference contract, whenever the owner (deployer) calls AdjustBetAmounts,
        // the bet limit becomes newLimit. We assert that if callerIsOwner is true then the call succeeded (ok==true)
        // and the getter reports the updated value. This is a universal property the reference satisfies for all inputs
        // and the mutant (owner check replaced by whale) will fail when callerIsOwner==true but whale!=owner.
        if (callerIsOwner) {
            // require that the call did not revert and the limit equals newLimit
            assertTrue(ok && c.currentBetLimit() == newLimit);
        } else {
            // For non-owner callers we do not assert anything about behavior; still must have exactly one assertTrue in all code paths,
            // so assert a tautology about reading the contract (compare currentBetLimit() to itself).
            assertTrue(c.currentBetLimit() == c.currentBetLimit());
        }
    }
}

