contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // fuzzed params: an address player and a uint256 betLimit (will be used to set contract betLimit via AdjustBetAmounts)
    function testFuzz_property(address player, uint256 betLimit) public {
        // keep betLimit > 0 so that wager() expects a positive value
        betLimit = bound(betLimit, 1, type(uint256).max);

        // make sure player is a real EOA for the test (fuzzer may supply contract addresses; we treat any address as an EOA by not deploying code)
        // fund the player so they can send ETH equal to betLimit
        vm.deal(player, betLimit);

        // owner is address(this) because constructor set owner = msg.sender in setUp
        // set the contract's bet limit to the fuzzed value
        c.AdjustBetAmounts(betLimit);

        // Owner opens to public
        c.OpenToThePublic();

        // Now have the fuzzed player attempt to wager with exact betLimit
        bool ok;
        vm.prank(player);
        try c.wager{value: betLimit}() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: after owner calls OpenToThePublic(), any EOA with exactly betLimit wei can successfully call wager()
        // (reference C sets openToPublic = true; mutant sets it false and will make this fail for some inputs)
        assertTrue(ok);
    }
}

