pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), 0); }

    // Fuzzed amount is the deciding parameter: for the correct contract, when owner calls
    // AdjustBetAmounts(amount) the public getter currentBetLimit() will equal amount.
    // The mutant omitted the assignment and will fail for some amounts. We let the fuzzer
    // find such an amount. We must be owner (setUp deployed c with address(this)).
    function testFuzz_property(uint256 amount) public {
        // keep domain wide; no tight assumptions
        // call as owner (this test contract)
        bool ok;
        try c.AdjustBetAmounts(amount) {
            ok = true;
        } catch {
            ok = false;
        }
        // single assertion: after calling, for the correct contract the getter equals amount
        // We assert that if the call succeeded, then currentBetLimit() == amount.
        // This will always hold on the reference; on the mutant it will fail for some amount
        // (the mutant emits event but does not assign betLimit), causing the assertion to fail.
        if (ok) {
            assertTrue(c.currentBetLimit() == amount);
        } else {
            // If the call reverted (shouldn't for owner), still assert false to indicate violation
            // but keep it as the single assertTrue required: assert that false == true will fail.
